import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL;

export const fetchResorts = async () => {
  try {
    const response = await axios.get(`${API_URL}/resorts`);
    return response.data || []; // Ensure an array is returned
  } catch (error) {
    console.error(error);
    return []; // Return an empty array on error
  }
};

export const fetchResort = async (name) => {
  try {
    const response = await axios.get(`${API_URL}/resort/${name}`);
    return response.data;
  } catch (error) {
    console.error(error);
    return null; // Return null on error
  }
};
